const topic = $('Set Topic').first().json.topic;
const seoText = $('AI - SEO Optimization').first().json.text; 
let blogPost = $('AI - Editor Checklist').first().json.text;

// HEADER-PRESERVING STRIPPER:
// This only removes the first line if it is a main Title. 
// It safely ignores all ## and ### headers.
let lines = blogPost.split('\n');

// Check if the very first line is likely a Title (e.g., contains '2026' or 'Guide')
// You can adjust this 'if' condition if it still misses the title.
if (lines[0].includes('2026') || lines[0].includes('Guide')) {
    lines.shift(); // Removes only the first line
}

blogPost = lines.join('\n').trim();

// ... (Rest of your extraction logic)

const extract = (label, text) => {
  const regex = new RegExp(label + ':\\s*(.+)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
};

const seoTitle = extract('SEO_TITLE', seoText);
const finalContent = blogPost + '\n\n---\nEDITOR NOTES: Focus Keyword: ' + extract('FOCUS_KEYWORD', seoText);

return [{
  json: {
    title: seoTitle || topic,
    content: finalContent, 
    // ... (rest of your object)
  }
}];
